import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"NVMeoF - What is new in Tentacle?","description":"","frontmatter":{"title":"NVMeoF - What is new in Tentacle?","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["NVMe","RBD","块存储","监控","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/NVMeoF_-_What_is_new_in_Tentacle.md","filePath":"posts/2026/NVMeoF_-_What_is_new_in_Tentacle.md","lastUpdated":null}'),l={name:"posts/2026/NVMeoF_-_What_is_new_in_Tentacle.md"};function o(n,a,s,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 Red Hat 产品经理 Mike Burkhart 在 Ceph London 大会上发表，内容为 NVMe over TCP（NVMeoF）在 Tentacle 版本中的新特性和改进。这是一次约 10 分钟的 Lightning Talk，涵盖了多个已合并或在研的关键功能。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="nvme-over-tcp-csi-driver" tabindex="-1">NVMe over TCP CSI Driver <a class="header-anchor" href="#nvme-over-tcp-csi-driver" aria-label="Permalink to &quot;NVMe over TCP CSI Driver&quot;">​</a></h3><p>针对用户希望将 NVMe over TCP 作为统一 block storage 协议的诉求，官方正式推出 CSI driver 支持：</p><ul><li>用户、开发者、客户均要求一个统一的 block storage 协议层</li><li>Microsoft 正在推出 initiator，Linux 原生 initiator 已经存在</li><li>目前处于 <strong>dev preview</strong> 阶段，已合并到主线</li><li><strong>Rook</strong> 同样支持此部署方式（upstream 非 official build，bits 已可用）</li><li>强烈建议不要将 dev preview 版本用于生产环境</li></ul><h3 id="spdk-top-工具" tabindex="-1">SPDK top 工具 <a class="header-anchor" href="#spdk-top-工具" aria-label="Permalink to &quot;SPDK top 工具&quot;">​</a></h3><p>新增命令行工具 <code>spdk top</code>，用于可视化 SPDK 和 NVMe namespace 的使用情况：</p><ul><li>可查看各 RBD image 的 IOPS、read、write、wait 等指标</li><li>支持 QoS 可视化</li><li>适用于性能 triage 和日常监控管理</li></ul><h3 id="默认-metadata-pool-自动化" tabindex="-1">默认 Metadata Pool 自动化 <a class="header-anchor" href="#默认-metadata-pool-自动化" aria-label="Permalink to &quot;默认 Metadata Pool 自动化&quot;">​</a></h3><ul><li>此前部署 NVMe service 需要手动创建 metadata pool</li><li>Tentacle 中已将此 pool 的创建自动化，类似 manager pool 的处理方式</li><li>该功能<strong>已提交到 main 分支</strong>（待确认）</li></ul><h3 id="listener-自动创建" tabindex="-1">Listener 自动创建 <a class="header-anchor" href="#listener-自动创建" aria-label="Permalink to &quot;Listener 自动创建&quot;">​</a></h3><ul><li>部署 SPDK gateway 时，listener（端口+IP 组合）现在会随 service 部署自动创建</li><li>支持提供 CIDR（IP 网络掩码和范围）</li><li>subsystem 添加命令行示例：一条命令即可添加 NVMe target 并投入使用</li><li>该功能<strong>已提交到 main 分支</strong>（待确认）</li></ul><h3 id="stretch-cluster-支持" tabindex="-1">Stretch Cluster 支持 <a class="header-anchor" href="#stretch-cluster-支持" aria-label="Permalink to &quot;Stretch Cluster 支持&quot;">​</a></h3><ul><li>NVMe stretch cluster 目前已支持 <strong>replica</strong> 模式</li><li><strong>EC（Erasure Coding）</strong> 模式尚不完善，与 fast EC for stretch 的改进配合后将大幅提升 multi-site 或 hybrid 部署的 block storage 能力</li><li>failover/failback 逻辑（包括 site-local reads 判断）部分已提交，其余逻辑仍在完善中</li></ul><h3 id="缩短-failover-时间" tabindex="-1">缩短 Failover 时间 <a class="header-anchor" href="#缩短-failover-时间" aria-label="Permalink to &quot;缩短 Failover 时间&quot;">​</a></h3><ul><li>原有 failover 时间平均约 <strong>12 秒</strong>：每个 gateway beacon 间隔约 1 秒，需丢失 3 个 beacon，再加上 5 秒检查周期和 10 秒最后 beacon 时间</li><li>Tentacle 已将 failover 时间压缩至 <strong>4~6 秒</strong></li><li><strong>subsecond 级 fast failover</strong> 正在研究中，尚未进入 committed 状态</li><li>已缩短的 failover 时间<strong>已在 Tentacle 中生效</strong></li></ul><h3 id="crc-校验复用" tabindex="-1">CRC 校验复用 <a class="header-anchor" href="#crc-校验复用" aria-label="Permalink to &quot;CRC 校验复用&quot;">​</a></h3><ul><li>原来 incoming CRC 校验在 gateway 侧和 RBD 侧各执行一次</li><li>正在集成 SPDK reactor core 与 RBD client 之间的逻辑，使同一 CRC 计算只执行一次</li><li>目前有 proof of concept，预计能加速写入处理，节省 CPU 资源</li><li>对小 IO 和对齐 IO 场景节省 CPU 效果明显</li></ul><h3 id="grafana-dashboard-上游化" tabindex="-1">Grafana Dashboard 上游化 <a class="header-anchor" href="#grafana-dashboard-上游化" aria-label="Permalink to &quot;Grafana Dashboard 上游化&quot;">​</a></h3><p>两套 dashboard 已上游化：</p><p><strong>总览 Dashboard：</strong></p><ul><li>Gateway 数量与健康状态</li><li>告警信息</li><li>Namespace 组概览、连接的集群、容量等</li></ul><p><strong>性能 Dashboard：</strong></p><ul><li>CPU 使用率</li><li>IO 延迟</li><li>按 gateway、subsystem 细分的指标</li><li>便于定位性能瓶颈</li></ul><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>NVMe over TCP CSI Driver (dev preview)</td><td>已合并</td></tr><tr><td>SPDK top 工具</td><td>Tentacle 新增</td></tr><tr><td>默认 Metadata Pool 自动化</td><td>已提交 main（待确认）</td></tr><tr><td>Listener 自动创建</td><td>已提交 main（待确认）</td></tr><tr><td>Stretch Cluster 支持（replica）</td><td>部分已提交</td></tr><tr><td>缩短 Failover 时间（4~6s）</td><td>已在 Tentacle 中生效</td></tr><tr><td>Fast Failover（subsecond）</td><td>研究中，未 committed</td></tr><tr><td>CRC 校验复用</td><td>Proof of concept 阶段</td></tr><tr><td>Grafana Dashboard 上游化</td><td>已完成</td></tr></tbody></table><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>验证 default metadata pool 和 listener autocreation 是否已正式合并到 main 分支</li><li>推进 Rook 中 NVMe over TCP CSI driver 从 dev preview 到 production 级别</li><li>完善 stretch cluster 中的 failover/failback 逻辑</li><li>推进 fast failover（subsecond 级别）的可行性研究</li><li>完成 CRC 校验复用的集成工作</li></ul><h2 id="参考信息" tabindex="-1">参考信息 <a class="header-anchor" href="#参考信息" aria-label="Permalink to &quot;参考信息&quot;">​</a></h2><ul><li>演讲者：Mike Burkhart，Red Hat NVMe over TCP 产品经理</li><li>工程负责人：Aviv（未出席现场）</li><li>活动：Ceph London 2026</li></ul>',31)])])}const b=e(l,[["render",o]]);export{p as __pageData,b as default};
